   !> SS(V)PE (gaussian charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs ssvpe_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_response(state, dv, hvp_v, error)
      !> State of ssvpe
      type(ssvpe_state), intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call ssvpe_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%ready < 3) then
         call fatal_error(error, "[ssvpe_response] call ssvpe_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call ssvpe_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine ssvpe_response

   !> One direction of ssvpe_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_response_one(state, dv, hvp_v, error)
      !> State of ssvpe
      type(ssvpe_state), target, intent(inout) :: state
      !> Direction for v
      real(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      real(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[ssvpe_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[ssvpe_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_response_one] allocation failed")
         return
      end if

      state%op1%points => state%r
      state%op1%a => state%a
      state%op1%c1 => state%s7
      state%op1%c3 => state%s12
      tmp1 = state%a*dv
      call gemv(state%s12, tmp1, tmp2)
      tmp3 = (-0.15915494309189535_wp)*tmp2
      tmp4 = dv + tmp3
      tmp5 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp4, tmp5, error)
      if (allocated(error)) return
      tmp6 = state%s15*tmp5
      tmp7 = 0.0_wp
      call state%solver%solve(state%op1, .false., dv, tmp7, error)
      if (allocated(error)) return
      tmp8 = state%s15*tmp7
      tmp9 = tmp6 + tmp8
      tmp10 = state%s17*tmp7
      call gemv(state%s12, tmp10, tmp11, trans="t")
      tmp12 = tmp11*state%a
      hvp_v = tmp9 + tmp12
   end subroutine ssvpe_response_one

   !> SS(V)PE (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs ssvpe_assemble on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_complex_medium(state, eps, error)
      !> State of ssvpe
      type(ssvpe_complex_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      complex(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      complex(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call ssvpe_complex_mf_medium(state, eps, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[ssvpe_complex_medium] call ssvpe_assemble first")
         return
      end if
      state%cx_ready = 0
      if (allocated(state%cx_v)) deallocate (state%cx_v)
      if (allocated(state%cx_s13)) deallocate (state%cx_s13)
      if (allocated(state%cx_s14)) deallocate (state%cx_s14)
      if (allocated(state%cx_s16)) deallocate (state%cx_s16)
      if (allocated(state%cx_s18)) deallocate (state%cx_s18)
      if (allocated(state%cx_s19)) deallocate (state%cx_s19)
      if (allocated(state%cx_s20)) deallocate (state%cx_s20)
      if (allocated(state%cx_s21)) deallocate (state%cx_s21)
      if (allocated(state%cx_s22)) deallocate (state%cx_s22)
      if (allocated(state%cx_s23)) deallocate (state%cx_s23)
      if (allocated(state%cx_s25)) deallocate (state%cx_s25)
      if (allocated(state%cx_s26)) deallocate (state%cx_s26)
      if (allocated(state%cx_s27)) deallocate (state%cx_s27)
      if (allocated(state%cx_s29)) deallocate (state%cx_s29)
      if (allocated(state%cx_s30)) deallocate (state%cx_s30)
      if (allocated(state%cx_s31)) deallocate (state%cx_s31)
      if (allocated(state%cx_s32)) deallocate (state%cx_s32)
      if (allocated(state%cx_s33)) deallocate (state%cx_s33)
      if (allocated(state%cx_s34)) deallocate (state%cx_s34)
      if (allocated(state%cx_s35)) deallocate (state%cx_s35)
      if (allocated(state%cx_s36)) deallocate (state%cx_s36)
      if (allocated(state%cx_s37)) deallocate (state%cx_s37)
      if (stat == 0) allocate (state%cx_v(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s13(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s14(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s16(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s18(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s19(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s20(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s21(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s22(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s23(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s25(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s26(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s27(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s29(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s30(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s31(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s32(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s33(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s34(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s35(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s36(npt), stat=stat)
      if (stat == 0) allocate (state%cx_s37(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_complex_medium] allocation failed")
         return
      end if
      state%cx_s14 = 0.0_wp
      state%cx_s16 = 0.0_wp
      state%cx_ready = 1
      state%cx_assembled = state%assembled
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op3%npt = npt
      state%op3%npoint = npt
      state%op3%id = 3
      state%op3%points => state%r
      state%op3%symmetric = .true.
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%cx_s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%cx_s1
      tmp2 = (-2.0_wp)*tmp1
      state%cx_s2 = 1.0_wp + tmp2
      state%cx_s8 = (-0.07957747154594767_wp)*state%cx_s2
      state%op3%c2 = state%cx_s8
      state%op3%c3 => state%s12
      call state%solver%setup_complex(state%op3, error)
      if (allocated(error)) return
      state%cx_s3 = -state%cx_s2
      state%cx_s15 = (-0.5_wp)*state%cx_s2
      state%cx_s17 = 0.07957747154594767_wp*state%cx_s2

      state%cx_ready = 2
   end subroutine ssvpe_complex_medium

   !> SS(V)PE (gaussian charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs ssvpe_complex_medium on the same state first
   !> - Complex variant: holomorphic arithmetic, transposes and never conjugates
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_complex_solve(state, v, energy, q, grad_v, error)
      !> State of ssvpe
      type(ssvpe_complex_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      complex(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      complex(wp), intent(out) :: energy
      !> Apparent surface charges
      complex(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      complex(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:), tmp6(:), tmp7(:), tmp14(:), tmp15(:), tmp18(:), &
                               tmp19(:), tmp21(:), tmp22(:), tmp25(:), tmp26(:)
      complex(wp), allocatable :: tmp1(:), tmp4(:), tmp5(:), tmp9(:), tmp10(:), tmp11(:), &
                                  tmp12(:), tmp13(:), tmp16(:), tmp17(:), tmp20(:), tmp23(:), &
                                  tmp24(:), tmp27(:), tmp28(:), tmp29(:), tmp30(:), tmp31(:)
      complex(wp) :: tmp8, tmp32

      if (state%matrix_free) then
         call ssvpe_complex_mf_solve(state, v, energy, q, grad_v, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%cx_ready < 2 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[ssvpe_complex_solve] call ssvpe_complex_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[ssvpe_complex_solve] v: wrong shape")
