      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call ssvpe_complex_mf_tangent(state, dr, dn, dk1, dk2, dxi, dF, da, dv, hvp_r, hvp_n, &
                                       hvp_k1, hvp_k2, hvp_xi, hvp_F, hvp_a, hvp_v, error)
         return
      end if
      if (state%cx_ready < 4 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[ssvpe_complex_tangent] call ssvpe_complex_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_tangent] dn: wrong shape")
         return
