      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_n) /= [3, npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_tangent] hvp_n: wrong shape")
         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
