         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_tangent] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call ssvpe_complex_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                        dk2(:, blk), dxi(:, blk), dF(:, blk), da(:, blk), &
