      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call ssvpe_complex_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[ssvpe_complex_response] call ssvpe_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_complex_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call ssvpe_complex_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine ssvpe_complex_response

   !> One direction of ssvpe_complex_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_complex_response_one(state, dv, hvp_v, error)
      !> State of ssvpe
      type(ssvpe_complex_state), target, intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp3(:), tmp4(:), tmp14(:), tmp15(:)
      complex(wp), allocatable :: tmp1(:), tmp2(:), tmp5(:), tmp6(:), tmp7(:), tmp8(:), tmp9(:), &
                                  tmp10(:), tmp11(:), tmp12(:), tmp13(:), tmp16(:)

      stat = 0
      npt = state%npt
      if (any(shape(dv) /= [npt])) then
         call fatal_error(error, "[ssvpe_complex_response_one] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt])) then
         call fatal_error(error, "[ssvpe_complex_response_one] hvp_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp3(npt), stat=stat)
      if (stat == 0) allocate (tmp4(npt), stat=stat)
      if (stat == 0) allocate (tmp5(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp10(npt), stat=stat)
      if (stat == 0) allocate (tmp11(npt), stat=stat)
      if (stat == 0) allocate (tmp12(npt), stat=stat)
      if (stat == 0) allocate (tmp13(npt), stat=stat)
      if (stat == 0) allocate (tmp14(npt), stat=stat)
      if (stat == 0) allocate (tmp15(npt), stat=stat)
      if (stat == 0) allocate (tmp16(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_complex_response_one] allocation failed")
         return
      end if

      state%op3%points => state%r
      state%op3%a => state%a
      state%op3%c1 => state%s7
      state%op3%c3 => state%s12
      tmp1 = state%a*dv
      call gemv(state%s12, real(tmp1, wp), tmp3)
      call gemv(state%s12, aimag(tmp1), tmp4)
      tmp2 = cmplx(tmp3, tmp4, wp)
      tmp5 = (-0.15915494309189535_wp)*tmp2
      tmp6 = dv + tmp5
      tmp7 = 0.0_wp
      call state%solver%solve_complex(state%op3, .false., tmp6, tmp7, error)
      if (allocated(error)) return
      tmp8 = state%cx_s15*tmp7
      tmp9 = 0.0_wp
      call state%solver%solve_complex(state%op3, .false., dv, tmp9, error)
      if (allocated(error)) return
      tmp10 = state%cx_s15*tmp9
      tmp11 = tmp8 + tmp10
      tmp12 = state%cx_s17*tmp9
      call gemv(state%s12, real(tmp12, wp), tmp14, trans="t")
      call gemv(state%s12, aimag(tmp12), tmp15, trans="t")
      tmp13 = cmplx(tmp14, tmp15, wp)
      tmp16 = tmp13*state%a
      hvp_v = tmp11 + tmp16
   end subroutine ssvpe_complex_response_one

   !> SS(V)PE (gaussian charges): build the cavity operators
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] r  positions of the surface points
   !> @param[in] n  outward unit normals at the surface points
   !> @param[in] k1  first principal curvature (positive where convex)
   !> @param[in] k2  second principal curvature (positive where convex)
   !> @param[in] xi  gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
   !> @param[in] F  switching function (1 where the grid is not switched)
   !> @param[in] a  grid point areas
   !> @param[out] error  error handling; allocated on failure
   !> @param[in] solver  linear solver, copied into the state; default dense LAPACK (Cholesky,
   !> symmetric or LU)
   subroutine ssvpe_mf_assemble(state, r, n, k1, k2, xi, F, a, error, solver)
      !> State of ssvpe
      type(ssvpe_state), target, intent(inout) :: state
      !> Positions of the surface points
      real(wp), contiguous, intent(in) :: r(:, :)
      !> Outward unit normals at the surface points
      real(wp), contiguous, intent(in) :: n(:, :)
      !> First principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k1(:)
      !> Second principal curvature (positive where convex)
      real(wp), contiguous, intent(in) :: k2(:)
      !> Gaussian widths of the surface charges (ISWIG: xi_Born/(R_I sqrt(w_i)))
      real(wp), contiguous, intent(in) :: xi(:)
      !> Switching function (1 where the grid is not switched)
      real(wp), contiguous, intent(in) :: F(:)
      !> Grid point areas
      real(wp), contiguous, intent(in) :: a(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error
      !> Linear solver
      class(pcm_solver), intent(in), optional :: solver

      integer :: npt
      integer :: stat

      stat = 0
      npt = size(r, 2)
      if (npt < 1) then
         call fatal_error(error, "[ssvpe_mf_assemble] empty discretization")
         return
      end if
      if (any(shape(r) /= [3, npt])) then
         call fatal_error(error, "[ssvpe_mf_assemble] r: wrong shape")
         return
      end if
      if (any(shape(n) /= [3, npt])) then
         call fatal_error(error, "[ssvpe_mf_assemble] n: wrong shape")
         return
      end if
      if (any(shape(k1) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_assemble] k1: wrong shape")
         return
      end if
      if (any(shape(k2) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_assemble] k2: wrong shape")
         return
      end if
      if (any(shape(xi) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_assemble] xi: wrong shape")
         return
      end if
      if (any(shape(F) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_assemble] F: wrong shape")
         return
      end if
      if (any(shape(a) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_assemble] a: wrong shape")
         return
      end if
      state%ready = 0
      if (allocated(state%solver)) deallocate (state%solver)
      if (allocated(state%v)) deallocate (state%v)
      if (allocated(state%xi)) deallocate (state%xi)
      if (allocated(state%r)) deallocate (state%r)
      if (allocated(state%F)) deallocate (state%F)
      if (allocated(state%n)) deallocate (state%n)
      if (allocated(state%k1)) deallocate (state%k1)
      if (allocated(state%k2)) deallocate (state%k2)
      if (allocated(state%a)) deallocate (state%a)
      if (allocated(state%s4)) deallocate (state%s4)
      if (allocated(state%s5)) deallocate (state%s5)
      if (allocated(state%s6)) deallocate (state%s6)
      if (allocated(state%s9)) deallocate (state%s9)
      if (allocated(state%s10)) deallocate (state%s10)
      if (allocated(state%s11)) deallocate (state%s11)
      if (allocated(state%s13)) deallocate (state%s13)
      if (allocated(state%s14)) deallocate (state%s14)
      if (allocated(state%s16)) deallocate (state%s16)
      if (allocated(state%s18)) deallocate (state%s18)
      if (allocated(state%s19)) deallocate (state%s19)
      if (allocated(state%s20)) deallocate (state%s20)
      if (allocated(state%s21)) deallocate (state%s21)
      if (allocated(state%s22)) deallocate (state%s22)
      if (allocated(state%s23)) deallocate (state%s23)
      if (allocated(state%s25)) deallocate (state%s25)
      if (allocated(state%s26)) deallocate (state%s26)
      if (allocated(state%s27)) deallocate (state%s27)
      if (allocated(state%s29)) deallocate (state%s29)
      if (allocated(state%s30)) deallocate (state%s30)
      if (allocated(state%s31)) deallocate (state%s31)
      if (allocated(state%s32)) deallocate (state%s32)
      if (allocated(state%s33)) deallocate (state%s33)
      if (allocated(state%s34)) deallocate (state%s34)
      if (allocated(state%s35)) deallocate (state%s35)
      if (allocated(state%s36)) deallocate (state%s36)
      if (allocated(state%s37)) deallocate (state%s37)
      if (allocated(state%s7)) deallocate (state%s7)
      if (allocated(state%s12)) deallocate (state%s12)
      state%npt = npt
      if (present(solver)) then
         allocate (state%solver, source=solver, stat=stat)
      else
         allocate (pcm_dense_solver :: state%solver, stat=stat)
      end if
      if (stat == 0) allocate (state%v(npt), stat=stat)
      if (stat == 0) allocate (state%xi(npt), stat=stat)
      if (stat == 0) allocate (state%r(3, npt), stat=stat)
      if (stat == 0) allocate (state%F(npt), stat=stat)
      if (stat == 0) allocate (state%n(3, npt), stat=stat)
      if (stat == 0) allocate (state%k1(npt), stat=stat)
      if (stat == 0) allocate (state%k2(npt), stat=stat)
      if (stat == 0) allocate (state%a(npt), stat=stat)
      if (stat == 0) allocate (state%s4(npt), stat=stat)
      if (stat == 0) allocate (state%s5(npt), stat=stat)
      if (stat == 0) allocate (state%s6(npt), stat=stat)
      if (stat == 0) allocate (state%s9(npt), stat=stat)
      if (stat == 0) allocate (state%s10(npt), stat=stat)
      if (stat == 0) allocate (state%s11(npt), stat=stat)
      if (stat == 0) allocate (state%s13(npt), stat=stat)
      if (stat == 0) allocate (state%s14(npt), stat=stat)
      if (stat == 0) allocate (state%s16(npt), stat=stat)
      if (stat == 0) allocate (state%s18(npt), stat=stat)
      if (stat == 0) allocate (state%s19(npt), stat=stat)
      if (stat == 0) allocate (state%s20(npt), stat=stat)
      if (stat == 0) allocate (state%s21(npt), stat=stat)
      if (stat == 0) allocate (state%s22(npt), stat=stat)
      if (stat == 0) allocate (state%s23(npt), stat=stat)
      if (stat == 0) allocate (state%s25(npt), stat=stat)
      if (stat == 0) allocate (state%s26(npt), stat=stat)
      if (stat == 0) allocate (state%s27(npt), stat=stat)
      if (stat == 0) allocate (state%s29(npt), stat=stat)
      if (stat == 0) allocate (state%s30(npt), stat=stat)
      if (stat == 0) allocate (state%s31(npt), stat=stat)
      if (stat == 0) allocate (state%s32(npt), stat=stat)
      if (stat == 0) allocate (state%s33(npt), stat=stat)
      if (stat == 0) allocate (state%s34(npt), stat=stat)
      if (stat == 0) allocate (state%s35(npt), stat=stat)
      if (stat == 0) allocate (state%s36(npt), stat=stat)
      if (stat == 0) allocate (state%s37(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_mf_assemble] allocation failed")
         return
      end if
      state%s14 = 0.0_wp
      state%s16 = 0.0_wp
      call state%solver%reset(ssvpe_n_operators)
      state%matrix_free = .true.

      state%xi = xi
      state%r = r
      state%F = F
      state%n = n
      state%k1 = k1
      state%k2 = k2
      state%a = a
      state%s4 = state%r(1, :)
      state%s5 = state%r(2, :)
      state%s6 = state%r(3, :)
      state%s9 = state%n(1, :)
      state%s10 = state%n(2, :)
      state%s11 = state%n(3, :)

      state%ready = 1
      state%assembled = state%assembled + 1
   end subroutine ssvpe_mf_assemble

   !> SS(V)PE (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs ssvpe_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_mf_medium(state, eps, error)
      !> State of ssvpe
      type(ssvpe_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2

      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[ssvpe_mf_medium] call ssvpe_assemble first")
         return
      end if
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => eps)
      end associate

      state%op2%npt = npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%symmetric = .true.
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%xi => state%xi
      state%op2%F => state%F
      state%op2%a => state%a
      state%s1 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%s1
      tmp2 = (-2.0_wp)*tmp1
      state%s2 = 1.0_wp + tmp2
      state%s8 = (-0.07957747154594767_wp)*state%s2
      state%op2%c1 = state%s8
      call state%solver%setup(state%op2, error)
      if (allocated(error)) return
      state%s3 = -state%s2
      state%s15 = (-0.5_wp)*state%s2
      state%s17 = 0.07957747154594767_wp*state%s2

      state%ready = 2
   end subroutine ssvpe_mf_medium

   !> SS(V)PE (gaussian charges): energy, solution and gradient for v
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs ssvpe_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of ssvpe
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
   !> @param[out] grad_v  partial derivative of the energy with respect to v
   !> @param[out] error  error handling; allocated on failure
   subroutine ssvpe_mf_solve(state, v, energy, q, grad_v, error)
      !> State of ssvpe
      type(ssvpe_state), target, intent(inout) :: state
      !> Solute electrostatic potential at the surface points
      real(wp), contiguous, intent(in) :: v(:)
      !> Solvation energy
      real(wp), intent(out) :: energy
      !> Apparent surface charges
      real(wp), contiguous, intent(out) :: q(:)
      !> Partial derivative of the energy with respect to v
      real(wp), contiguous, intent(out) :: grad_v(:)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp), allocatable :: tmp1(:), tmp2(:), tmp6(:), tmp7(:), tmp8(:), tmp9(:), tmp146(:), &
                               tmp148(:), tmp149(:), tmp150(:), tmp151(:), tmp152(:), tmp153(:), &
                               tmp157(:), tmp257(:), tmp258(:), tmp259(:), tmp389(:), tmp390(:), &
                               tmp521(:), tmp522(:), tmp523(:), tmp624(:), tmp625(:), tmp626(:), &
                               tmp627(:), tmp628(:)
      real(wp) :: tmp3, tmp4, tmp5, tmp147, tmp154, tmp155, tmp156, tmp629
      integer :: i, j

      stat = 0
      npt = state%npt
      if (state%ready < 2) then
         call fatal_error(error, "[ssvpe_mf_solve] call ssvpe_medium first")
         return
      end if
      if (any(shape(v) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[ssvpe_mf_solve] grad_v: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp7(npt), stat=stat)
      if (stat == 0) allocate (tmp8(npt), stat=stat)
      if (stat == 0) allocate (tmp9(npt), stat=stat)
      if (stat == 0) allocate (tmp146(npt), stat=stat)
      if (stat == 0) allocate (tmp148(npt), stat=stat)
      if (stat == 0) allocate (tmp149(npt), stat=stat)
      if (stat == 0) allocate (tmp150(npt), stat=stat)
      if (stat == 0) allocate (tmp151(npt), stat=stat)
      if (stat == 0) allocate (tmp152(npt), stat=stat)
      if (stat == 0) allocate (tmp153(npt), stat=stat)
      if (stat == 0) allocate (tmp157(npt), stat=stat)
      if (stat == 0) allocate (tmp257(npt), stat=stat)
      if (stat == 0) allocate (tmp258(npt), stat=stat)
      if (stat == 0) allocate (tmp259(npt), stat=stat)
      if (stat == 0) allocate (tmp389(npt), stat=stat)
      if (stat == 0) allocate (tmp390(npt), stat=stat)
      if (stat == 0) allocate (tmp521(npt), stat=stat)
      if (stat == 0) allocate (tmp522(npt), stat=stat)
      if (stat == 0) allocate (tmp523(npt), stat=stat)
      if (stat == 0) allocate (tmp624(npt), stat=stat)
      if (stat == 0) allocate (tmp625(npt), stat=stat)
      if (stat == 0) allocate (tmp626(npt), stat=stat)
      if (stat == 0) allocate (tmp627(npt), stat=stat)
      if (stat == 0) allocate (tmp628(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_mf_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%xi => state%xi
      state%op2%F => state%F
      state%op2%a => state%a
      state%v = v
      state%s13 = state%a*state%v
      call state%solver%solve(state%op2, .false., state%v, state%s16, error)
      if (allocated(error)) return
      state%s18 = state%s17*state%s16
      do i = 1, npt
         tmp3 = state%k1(i) + state%k2(i)
         tmp4 = tmp3*state%xi(i)
         tmp5 = (-0.19947114020071635_wp)*tmp4
         tmp2(i) = tmp5
      end do
      tmp6 = tmp2*state%s13
      tmp7 = (-0.15915494309189535_wp)*tmp6
      tmp1 = tmp7
      tmp9 = tmp2*state%s18
      tmp8 = tmp9
      !$omp parallel default(none) &
      !$omp& private(i, j) &
      !$omp& shared(npt, state, tmp8) &
      !$omp& reduction(+: tmp1)
      block
         real(wp) :: tmp10(npt)
         real(wp) :: tmp12, tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp22, tmp23, &
                     tmp26, tmp30, tmp11

         !$omp do schedule(static)
         do j = 1, npt
            tmp12 = state%s13(j)
            tmp13 = state%xi(j)
            tmp14 = state%s4(j)
            tmp15 = state%s5(j)
            tmp16 = state%s6(j)
            tmp17 = state%s9(j)
            tmp18 = state%s10(j)
            tmp19 = state%s11(j)
            tmp20 = state%s18(j)
            tmp22 = tmp13**(2)
            tmp23 = -tmp14
            tmp26 = -tmp15
            tmp30 = -tmp16
            tmp11 = 0.0_wp
            !$omp simd &
            !$omp& reduction(+: tmp11)
            do i = 1, j - 1
               block
                  real(wp) :: tmp21, tmp24, tmp25, tmp27, tmp28, tmp29, tmp31, tmp32, tmp33, &
                              tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, &
                              tmp43, tmp44, tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, &
                              tmp52, tmp53

                  tmp24 = state%s4(i) + tmp23
                  tmp25 = tmp24**(2)
                  tmp27 = state%s5(i) + tmp26
                  tmp28 = tmp27**(2)
                  tmp29 = tmp25 + tmp28
                  tmp31 = state%s6(i) + tmp30
                  tmp32 = tmp31**(2)
                  tmp33 = tmp29 + tmp32
                  tmp34 = tmp22*tmp33
                  tmp35 = state%xi(i)**(2)
                  tmp36 = tmp34*tmp35
                  tmp37 = tmp35 + tmp22
                  tmp38 = (-81.0_wp)*tmp37
                  tmp39 = tmp36 + tmp38
                  tmp21 = 0.5_wp + sign(0.5_wp, tmp39)
                  tmp10(i) = tmp21
                  tmp40 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp39))
                  tmp41 = tmp33 + tmp40
                  tmp42 = 1.0_wp/sqrt(tmp41)
                  tmp43 = tmp42**(3)
                  tmp44 = tmp12*tmp43
                  tmp45 = tmp17*tmp24
                  tmp46 = tmp27*tmp18
                  tmp47 = tmp45 + tmp46
                  tmp48 = tmp31*tmp19
                  tmp49 = tmp47 + tmp48
                  tmp50 = tmp44*tmp49
                  tmp51 = (-0.15915494309189535_wp)*tmp50
                  tmp1(i) = tmp1(i) + tmp51*tmp21
