         call fatal_error(error, "[ssvpe_mf_tangent] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_r) /= [3, npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_r: wrong shape")
         return
      end if
      if (any(shape(hvp_n) /= [3, npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_n: wrong shape")
         return
      end if
      if (any(shape(hvp_k1) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_k1: wrong shape")
         return
      end if
      if (any(shape(hvp_k2) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_k2: wrong shape")
         return
      end if
      if (any(shape(hvp_xi) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_xi: wrong shape")
         return
      end if
      if (any(shape(hvp_F) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_F: wrong shape")
         return
      end if
      if (any(shape(hvp_a) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_a: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[ssvpe_mf_tangent] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call ssvpe_mf_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), dk2(:, blk), &
                                   dxi(:, blk), dF(:, blk), da(:, blk), dv(:, blk), &
                                   hvp_r(:, :, blk), hvp_n(:, :, blk), hvp_k1(:, blk), &
                                   hvp_k2(:, blk), hvp_xi(:, blk), hvp_F(:, blk), hvp_a(:, blk), &
                                   hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
