         return
      end if
      do blk = 1, nblk
         call ssvpe_complex_mf_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                           dk2(:, blk), dxi(:, blk), dF(:, blk), da(:, blk), &
