   !> Apply operator 1 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine ssvpe_op1_apply(self, trans, x, y)
      !> Operator
      class(ssvpe_op1), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp4(self%npt), &
                        tmp5(self%npt), tmp6(self%npt), tmp7(self%npt), tmp8(self%npt), &
                        tmp9(self%npt)

            call gemv(self%c1, x, tmp1, trans="t")
            call gemv(self%c3, x, tmp2, trans="t")
            tmp3 = self%a*tmp2
            call gemv(self%c1, tmp3, tmp4, trans="t")
            call gemv(self%c1, x, tmp5)
            tmp6 = self%a*tmp5
            call gemv(self%c3, tmp6, tmp7)
            tmp8 = tmp4 + tmp7
            tmp9 = self%c2*tmp8
            y = tmp1 + tmp9
         end block
      else
         block
            real(wp) :: tmp1(self%npt), tmp2(self%npt), tmp3(self%npt), tmp4(self%npt), &
                        tmp5(self%npt), tmp6(self%npt), tmp7(self%npt), tmp8(self%npt)

            call gemv(self%c1, x, tmp1)
            tmp2 = self%a*tmp1
            call gemv(self%c3, tmp2, tmp3)
            call gemv(self%c3, x, tmp4, trans="t")
            tmp5 = self%a*tmp4
            call gemv(self%c1, tmp5, tmp6, trans="t")
            tmp7 = tmp3 + tmp6
            tmp8 = self%c2*tmp7
            y = tmp1 + tmp8
         end block
      end if
   end subroutine ssvpe_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine ssvpe_op1_assemble(self, a, error)
      !> Operator
      class(ssvpe_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp5(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_op1_assemble] allocation failed")
         return
      end if
      do i = 1, self%npt
         tmp1(:, i) = self%a(i)*self%c3(:, i)
      end do
      call gemm(tmp1, self%c1, tmp2)
      tmp3 = transpose(tmp2)
      tmp4 = tmp2 + tmp3
      tmp5 = self%c2*tmp4
      a = self%c1 + tmp5
   end subroutine ssvpe_op1_assemble

   !> Form operator 1 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine ssvpe_op1_assemble_block(self, idx, a, error)
      !> Operator
      class(ssvpe_op1), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :), tmp6(:, :), &
                               tmp7(:, :), tmp8(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[ssvpe_op1_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp7(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp8(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[ssvpe_op1_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%a(idx)
      tmp2 = self%c1(idx, idx)
      tmp3 = self%c3(idx, idx)
      do i = 1, nb
         tmp4(:, i) = tmp1(i)*tmp3(:, i)
      end do
      call gemm(tmp4, tmp2, tmp5)
      tmp6 = transpose(tmp5)
      tmp7 = tmp5 + tmp6
      tmp8 = self%c2*tmp7
      a = tmp2 + tmp8
   end subroutine ssvpe_op1_assemble_block

   !> Apply operator 2 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine ssvpe_op2_apply(self, trans, x, y)
      !> Operator
      class(ssvpe_op2), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

