                                    tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, &
                                    tmp36

                        tmp17 = self%r(1, i) + tmp16
                        tmp18 = tmp17**(2)
                        tmp20 = self%r(2, i) + tmp19
                        tmp21 = tmp20**(2)
                        tmp22 = tmp18 + tmp21
                        tmp24 = self%r(3, i) + tmp23
                        tmp25 = tmp24**(2)
                        tmp26 = tmp22 + tmp25
                        tmp27 = tmp15*tmp26
